// The exercise list the program builder picks from: one standard name per movement (the same names the
// how-to pictures carry, so a picked exercise gets its picture automatically once pictures ship).
// Generated by tests/tools/exercise-catalog.build.test.ts into public/data/exercise-catalog.json and
// fetched lazily the first time the picker opens.

export interface CatalogExercise {
  name: string;
  // other names people use for the same movement (searchable, not shown)
  aka: string[];
  // movement pattern, e.g. 'Push', 'Hinge', 'Core'
  pattern: string;
  equip: string;
  // muscle groups worked (from the researched how-to data; empty when not verified yet)
  primary: string[];
  secondary: string[];
  // sports whose programs use this movement
  sports: string[];
  // how many program exercises use it (sort order)
  uses: number;
}

export interface CatalogData {
  exercises: CatalogExercise[];
  sports: string[];
  patterns: string[];
  muscles: string[];
}

let catalogPromise: Promise<CatalogData | null> | null = null;
export function loadExerciseCatalog(): Promise<CatalogData | null> {
  if (!catalogPromise) {
    catalogPromise = fetch('/data/exercise-catalog.json')
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null);
  }
  return catalogPromise;
}

const SYN: [RegExp, string][] = [
  [/\bdb\b/g, 'dumbbell'], [/\bkb\b/g, 'kettlebell'], [/\bbb\b/g, 'barbell'], [/\brdl\b/g, 'romanian deadlift'],
  [/\bpress[- ]?ups?\b/g, 'push up'], [/\bpush[- ]?ups?\b/g, 'push up'], [/\bpull[- ]?ups?\b/g, 'pull up'],
  [/\bchin[- ]?ups?\b/g, 'chin up'], [/\bsit[- ]?ups?\b/g, 'sit up'], [/\bstep[- ]?ups?\b/g, 'step up'],
  [/\bpull[- ]?downs?\b/g, 'pulldown'], [/\bbicep\b/g, 'biceps'], [/\btricep\b/g, 'triceps'], [/\babs\b/g, 'core'],
];
export function searchWords(s: string): string[] {
  let t = ' ' + s.toLowerCase().replace(/[’']/g, '') + ' ';
  for (const [re, rep] of SYN) t = t.replace(re, rep);
  return t.replace(/[^a-z0-9]+/g, ' ').trim().split(/\s+/).filter(Boolean)
    .map((w) => (/(ch|sh|x)es$/.test(w) ? w.slice(0, -2) : w.length > 3 && /[^s]s$/.test(w) ? w.slice(0, -1) : w));
}

export interface CatalogFilters {
  sport?: string | null;
  pattern?: string | null;
  muscle?: string | null;
}

// Every typed word must start a word in the exercise's name or one of its other names ("db bench" finds
// "Dumbbell Bench Press"). Ranked: name starts with the query, then whole-word name matches, then matches
// only via another name, then how widely the movement is used.
export function searchExercises(list: CatalogExercise[], query: string, f: CatalogFilters = {}): CatalogExercise[] {
  const q = searchWords(query);
  const scored: { e: CatalogExercise; s: number }[] = [];
  for (const e of list) {
    if (f.sport && !e.sports.includes(f.sport)) continue;
    if (f.pattern && e.pattern !== f.pattern) continue;
    if (f.muscle && !e.primary.includes(f.muscle) && !e.secondary.includes(f.muscle)) continue;
    if (!q.length) { scored.push({ e, s: 0 }); continue; }
    const nameW = searchWords(e.name);
    const inName = q.every((w) => nameW.some((x) => x.startsWith(w)));
    const inAka = !inName && e.aka.some((a) => { const aw = searchWords(a); return q.every((w) => aw.some((x) => x.startsWith(w))); });
    if (!inName && !inAka) continue;
    let s = inName ? 100 : 40;
    if (inName && nameW.join(' ').startsWith(q.join(' '))) s += 60;
    if (inName && q.every((w) => nameW.includes(w))) s += 25;
    if (f.muscle && e.primary.includes(f.muscle)) s += 10;
    scored.push({ e, s });
  }
  return scored.sort((a, b) => b.s - a.s || b.e.uses - a.e.uses || a.e.name.localeCompare(b.e.name)).map((x) => x.e);
}

// True when the typed text is already exactly one of the list's names (then no "add your own" row).
export function isExactCatalogName(list: CatalogExercise[], text: string): boolean {
  const t = searchWords(text).join(' ');
  return !!t && list.some((e) => searchWords(e.name).join(' ') === t || e.aka.some((a) => searchWords(a).join(' ') === t));
}
